Component2D.WithinRelation containsXYComponent(byte[] triangle) {
  decodeTriangle(triangle, this.xyQueryTriangle);
  DecodedTriangle scratch = this.xyQueryTriangle;
  switch (scratch.type) {
    case POINT:
      {
        double y = decodeXY(scratch.aY);
        double x = decodeXY(scratch.aX);
        return this.xyQueryComponent.withinPoint(x, y);
      }
    case LINE:
      {
        double aY = decodeXY(scratch.aY);
        double aX = decodeXY(scratch.aX);
        double bY = decodeXY(scratch.bY);
        double bX = decodeXY(scratch.bX);
        return this.xyQueryComponent.withinLine(aX, aY, scratch.ab, bX, bY);
      }
    case TRIANGLE:
      {
        double aY = decodeXY(scratch.aY);
        double aX = decodeXY(scratch.aX);
        double bY = decodeXY(scratch.bY);
        double bX = decodeXY(scratch.bX);
        double cY = decodeXY(scratch.cY);
        double cX = decodeXY(scratch.cX);
        return this.xyQueryComponent.withinTriangle(
            aX, aY, scratch.ab, bX, bY, scratch.bc, cX, cY, scratch.ca);
      }
    default:
      throw new IllegalArgumentException("Unsupported triangle type :[" + scratch.type + "]");
  }
}


LatLonShapeDocValuesField latLonPolygonDocValues(
    String fieldName, Polygon polygon, boolean checkSelfIntersections) {
  List<Tessellator.Triangle> tessellation =
      tessellateLatLonPolygon(polygon, checkSelfIntersections);
  this.docValueTriangles = new ArrayList<>(tessellation.size());
  this.docValueHighestType = DecodedTriangle.TYPE.TRIANGLE;
  resetDocValueBounds();
  for (int i = 0; i < tessellation.size(); i++) {
    this.docValueTriangles.add(buildDecodedTriangleFromTessellator(tessellation.get(i)));
  }
  return new LatLonShapeDocValuesField(fieldName, this.docValueTriangles);
}

LatLonShapeDocValuesField latLonLineDocValues(String fieldName, Line line) {
  int numPoints = line.numPoints();
  this.docValueTriangles = new ArrayList<>(Math.max(0, numPoints - 1));
  this.docValueHighestType = DecodedTriangle.TYPE.LINE;
  resetDocValueBounds();
  for (int i = 0, j = 1; j < numPoints; ++i, ++j) {
    DecodedTriangle triangle = new DecodedTriangle();
    triangle.type = DecodedTriangle.TYPE.LINE;
    int ax = encodeLon(line.getLon(i));
    int ay = encodeLat(line.getLat(i));
    int bx = encodeLon(line.getLon(j));
    int by = encodeLat(line.getLat(j));
    triangle.setValues(ax, ay, true, bx, by, true, ax, ay, true);
    accumulateDocValueBounds(triangle);
    this.docValueTriangles.add(triangle);
  }
  return new LatLonShapeDocValuesField(fieldName, this.docValueTriangles);
}

LatLonShapeDocValuesField latLonPointDocValues(String fieldName, double lat, double lon) {
  this.docValueTriangles = new ArrayList<>(1);
  this.docValueHighestType = DecodedTriangle.TYPE.POINT;
  resetDocValueBounds();
  DecodedTriangle triangle = new DecodedTriangle();
  triangle.type = DecodedTriangle.TYPE.POINT;
  int x = encodeLon(lon);
  int y = encodeLat(lat);
  triangle.setValues(x, y, true, x, y, true, x, y, true);
  accumulateDocValueBounds(triangle);
  this.docValueTriangles.add(triangle);
  return new LatLonShapeDocValuesField(fieldName, this.docValueTriangles);
}

LatLonShapeDocValuesField latLonFieldsDocValues(String fieldName, Field[] indexableFields) {
  this.docValueTriangles = new ArrayList<>(indexableFields.length);
  resetDocValueBounds();
  this.docValueHighestType = DecodedTriangle.TYPE.POINT;
  decodeIndexableToTriangles(indexableFields);
  return new LatLonShapeDocValuesField(fieldName, this.docValueTriangles);
}

